import React, { useState } from 'react';
import { Home, Compass, Video, MessageSquare, User, ArrowLeft, ShoppingBag } from 'lucide-react';

// ==========================================
// 1. IMPORT SEMUA KOMPONEN KAMU
// ==========================================
import AkunSaya from './akunsaya';
import Alamat from './alamat';
import BankEwallet from './bankewallet';
import BelumDibayar from './belumdibayar';
import Beranda from './beranda';
import BeriNilai from './berinilai';
import Chat from './chat';
import Chekout from './chekout';
import Dikemas from './dikemas';
import Dikirim from './dikirim';
import Email from './email';
import HubungiCS from './hubungics';
import Keranjang from './keranjang';
import Laporan from './laporan';
import Live from './live';
import MasukKeranjang from './masukkeranjang';
import Nama from './nama';
import NomerHp from './nomerhp';
import Produk from './produk';
import Saldo from './saldo';
import TarikDana from './tarikdana';
import TambahProduk from './tambahproduk';
import Selesai from './selesai';

// Halaman Pembeli & Penjual (Sesuaikan nama file jika belum di-rename)
import Pembeli from './pembeli';
import Penjual from './penjual';

export default function App() {
  // State halaman yang sedang aktif
    const [currentPage, setCurrentPage] = useState('beranda');
      
        // Riwayat halaman (supaya bisa tombol Back)
          const [history, setHistory] = useState(['beranda']);
            
              // State data jika ingin passing data antar halaman (misal: ID produk yang dipilih)
                const [pageData, setPageData] = useState(null);

                  // Fungsi Pindah Halaman
                    const navigate = (pageName, data = null) => {
                        setPageData(data);
                            setHistory((prev) => [...prev, pageName]);
                                setCurrentPage(pageName);
                                    window.scrollTo({ top: 0, behavior: 'smooth' });
                                      };

                                        // Fungsi Kembali ke Halaman Sebelumnya
                                          const goBack = () => {
                                              if (history.length > 1) {
                                                    const newHistory = [...history];
                                                          newHistory.pop(); // buang halaman terakhir
                                                                const previousPage = newHistory[newHistory.length - 1];
                                                                      setHistory(newHistory);
                                                                            setCurrentPage(previousPage);
                                                                                } else {
                                                                                      setCurrentPage('beranda');
                                                                                          }
                                                                                            };

                                                                                              // ==========================================
                                                                                                // 2. LOGIKA RENDER KOMPONEN
                                                                                                  // ==========================================
                                                                                                    const renderCurrentPage = () => {
                                                                                                        // Props standar yang dikirim ke setiap komponen:
                                                                                                            // navigate: untuk pindah halaman
                                                                                                                // goBack: untuk kembali
                                                                                                                    // data: data opsional (misal detail barang)
                                                                                                                        const commonProps = { navigate, goBack, data: pageData };

                                                                                                                            switch (currentPage) {
                                                                                                                                  case 'beranda':
                                                                                                                                          return <Beranda {...commonProps} />;
                                                                                                                                                case 'produk':
                                                                                                                                                        return <Produk {...commonProps} />;
                                                                                                                                                              case 'masukkeranjang':
                                                                                                                                                                      return <MasukKeranjang {...commonProps} />;
                                                                                                                                                                            case 'keranjang':
                                                                                                                                                                                    return <Keranjang {...commonProps} />;
                                                                                                                                                                                          case 'chekout':
                                                                                                                                                                                                  return <Chekout {...commonProps} />;
                                                                                                                                                                                                        
                                                                                                                                                                                                              // Pesanan
                                                                                                                                                                                                                    case 'belumdibayar':
                                                                                                                                                                                                                            return <BelumDibayar {...commonProps} />;
                                                                                                                                                                                                                                  case 'dikemas':
                                                                                                                                                                                                                                          return <Dikemas {...commonProps} />;
                                                                                                                                                                                                                                                case 'dikirim':
                                                                                                                                                                                                                                                        return <Dikirim {...commonProps} />;
                                                                                                                                                                                                                                                              case 'selesai':
                                                                                                                                                                                                                                                                      return <Selesai {...commonProps} />;
                                                                                                                                                                                                                                                                            case 'berinilai':
                                                                                                                                                                                                                                                                                    return <BeriNilai {...commonProps} />;

                                                                                                                                                                                                                                                                                          // Keuangan & Saldo
                                                                                                                                                                                                                                                                                                case 'saldo':
                                                                                                                                                                                                                                                                                                        return <Saldo {...commonProps} />;
                                                                                                                                                                                                                                                                                                              case 'tarikdana':
                                                                                                                                                                                                                                                                                                                      return <TarikDana {...commonProps} />;
                                                                                                                                                                                                                                                                                                                            case 'bankewallet':
                                                                                                                                                                                                                                                                                                                                    return <BankEwallet {...commonProps} />;

                                                                                                                                                                                                                                                                                                                                          // Akun & Pengaturan Profil
                                                                                                                                                                                                                                                                                                                                                case 'akunsaya':
                                                                                                                                                                                                                                                                                                                                                        return <AkunSaya {...commonProps} />;
                                                                                                                                                                                                                                                                                                                                                              case 'alamat':
                                                                                                                                                                                                                                                                                                                                                                      return <Alamat {...commonProps} />;
                                                                                                                                                                                                                                                                                                                                                                            case 'nama':
                                                                                                                                                                                                                                                                                                                                                                                    return <Nama {...commonProps} />;
                                                                                                                                                                                                                                                                                                                                                                                          case 'email':
                                                                                                                                                                                                                                                                                                                                                                                                  return <Email {...commonProps} />;
                                                                                                                                                                                                                                                                                                                                                                                                        case 'nomerhp':
                                                                                                                                                                                                                                                                                                                                                                                                                return <NomerHp {...commonProps} />;

                                                                                                                                                                                                                                                                                                                                                                                                                      // Komunikasi & Live
                                                                                                                                                                                                                                                                                                                                                                                                                            case 'chat':
                                                                                                                                                                                                                                                                                                                                                                                                                                    return <Chat {...commonProps} />;
                                                                                                                                                                                                                                                                                                                                                                                                                                          case 'hubungics':
                                                                                                                                                                                                                                                                                                                                                                                                                                                  return <HubungiCS {...commonProps} />;
                                                                                                                                                                                                                                                                                                                                                                                                                                                        case 'live':
                                                                                                                                                                                                                                                                                                                                                                                                                                                                return <Live {...commonProps} />;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // Mode Toko / Penjual
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            case 'penjual':
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return <HalamanPenjual {...commonProps} />;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          case 'pembeli':
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return <HalamanPembeli {...commonProps} />;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        case 'tambahproduk':
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return <TambahProduk {...commonProps} />;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      case 'laporan':
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return <Laporan {...commonProps} />;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    default:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return <Beranda {...commonProps} />;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // Sembunyikan bottom bar di halaman detail/checkout/pengaturan tertentu agar terlihat seperti aplikasi asli
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const hideBottomNavPages = [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          'chekout', 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              'chat', 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  'hubungics', 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      'tambahproduk', 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          'nama', 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              'email', 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  'nomerhp', 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      'alamat',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          'bankewallet',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              'tarikdana'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const shouldShowBottomNav = !hideBottomNavPages.includes(currentPage);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div className="bg-neutral-100 min-h-screen text-slate-800 antialiased font-sans">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <main className="max-w-md mx-auto bg-white min-h-screen relative shadow-2xl pb-20 border-x border-slate-200">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {/* Tombol Back Global (Muncul otomatis selain di halaman Beranda) */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {currentPage !== 'beranda' && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div className="sticky top-0 z-50 bg-white/95 backdrop-blur-md border-b border-slate-100 px-4 py-3 flex items-center gap-3">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <button 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          onClick={goBack} 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        className="p-1.5 rounded-full hover:bg-slate-100 text-slate-700 transition"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <ArrowLeft className="w-5 h-5" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <h2 className="text-sm font-bold capitalize text-slate-800 truncate">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {currentPage.replace(/([A-Z])/g, ' $1')}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </h2>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      )}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {/* RENDER HALAMAN AKTIF */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div className="min-h-[80vh]">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {renderCurrentPage()}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {/* BOTTOM NAVIGATION BAR */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {shouldShowBottomNav && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <nav className="fixed bottom-0 left-0 right-0 z-40 max-w-md mx-auto bg-white/95 backdrop-blur-md border-t border-slate-200 px-6 py-2.5 flex justify-between items-center shadow-lg">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            onClick={() => navigate('beranda')}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          className={`flex flex-col items-center gap-1 transition ${currentPage === 'beranda' ? 'text-amber-600 font-bold' : 'text-slate-400 hover:text-slate-700'}`}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <Home className="w-5 h-5" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <span className="text-[10px]">Beranda</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </button>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        onClick={() => navigate('live')}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      className={`flex flex-col items-center gap-1 transition ${currentPage === 'live' ? 'text-amber-600 font-bold' : 'text-slate-400 hover:text-slate-700'}`}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <Video className="w-5 h-5" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <span className="text-[10px]">Live</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </button>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    onClick={() => navigate('chat')}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  className={`flex flex-col items-center gap-1 transition ${currentPage === 'chat' ? 'text-amber-600 font-bold' : 'text-slate-400 hover:text-slate-700'}`}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <MessageSquare className="w-5 h-5" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <span className="text-[10px]">Chat</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </button>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                onClick={() => navigate('keranjang')}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              className={`flex flex-col items-center gap-1 transition ${currentPage === 'keranjang' ? 'text-amber-600 font-bold' : 'text-slate-400 hover:text-slate-700'}`}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <ShoppingBag className="w-5 h-5" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <span className="text-[10px]">Keranjang</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </button>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            onClick={() => navigate('akunsaya')}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          className={`flex flex-col items-center gap-1 transition ${currentPage === 'akunsaya' ? 'text-amber-600 font-bold' : 'text-slate-400 hover:text-slate-700'}`}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <User className="w-5 h-5" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <span className="text-[10px]">Saya</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </nav>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </main>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }